final readonly class OperationalReturnAuthorizationService
{
 private string$executions;private string$occupancy;private string$custody;private string$authorizations;
 public function __construct(#[Autowire('%kernel.project_dir%')]string$root){$this->executions=$root.'/var/imperium/mission/bounded-executions';$this->occupancy=$root.'/var/imperium/offices/curia/occupancy';$this->custody=$root.'/var/imperium/offices/garrison/custody';$this->authorizations=$root.'/var/imperium/offices/curia/operational-return-authorizations';}
 public function authorize(string$executionId,string$seneschalBindingId):array
 {
  if(!preg_match('/^bounded-operational-execution-[a-f0-9]{20}$/',$executionId))throw new \InvalidArgumentException('C217_BOUNDED_EXECUTION_ID_INVALID');$e=$this->read($this->executions.'/'.$executionId.'.json','C218_BOUNDED_EXECUTION_ABSENT');$s=$this->read($this->occupancy.'/'.$seneschalBindingId.'.json','C219_SENESCHAL_OCCUPANCY_ABSENT');
  foreach(glob($this->authorizations.'/operational-return-authorization-*.json')?:[]as$p){$x=$this->read($p,'C222_OPERATIONAL_RETURN_AUTHORIZATION_CONFLICT');if(!$this->ok($x))throw new \RuntimeException('C222_OPERATIONAL_RETURN_AUTHORIZATION_CONFLICT');if(($x['source_bounded_execution']['id']??null)===$executionId){if(($x['source_bounded_execution']['digest']??null)!==($e['record_digest']??null)||($x['authorizer']['binding_id']??null)!==$seneschalBindingId)throw new \RuntimeException('C222_OPERATIONAL_RETURN_AUTHORIZATION_CONFLICT');return$x;}}
